<script setup lang="ts">
import { invoke } from "@tauri-apps/api/core";
import { computed, onMounted, ref } from "vue";
import { Package, Plus, RefreshCw, X } from "lucide-vue-next";
import PaginationControls from "../components/PaginationControls.vue";
interface Product { id: number; name: string; category_name: string | null; description: string | null; variant_count: number; is_active: boolean }
interface Category { id: number; name: string }
const products = ref<Product[]>([]); const categories = ref<Category[]>([]); const page = ref(1); const pageSize = 8; const name = ref(""); const categoryId = ref<number | null>(null); const description = ref(""); const editingId = ref<number | null>(null); const loading = ref(true); const saving = ref(false); const error = ref("");
const pagedProducts = computed(() => products.value.slice((page.value - 1) * pageSize, page.value * pageSize));
async function load() { loading.value = true; error.value = ""; try { [products.value, categories.value] = await Promise.all([invoke<Product[]>("list_products"), invoke<Category[]>("list_categories")]); page.value = 1; } catch (e) { error.value = String(e); } finally { loading.value = false; } }
function edit(product: Product) { editingId.value = product.id; name.value = product.name; categoryId.value = categories.value.find((category) => category.name === product.category_name)?.id ?? null; description.value = product.description ?? ""; }
function cancelEdit() { editingId.value = null; name.value = ""; categoryId.value = null; description.value = ""; }
async function save() { if (!name.value.trim()) { error.value = "Nama produk wajib diisi."; return; } saving.value = true; error.value = ""; try { const input = { name: name.value, category_id: categoryId.value, description: description.value || null }; if (editingId.value) await invoke("update_product", { input: { ...input, id: editingId.value } }); else await invoke("create_product", { input }); cancelEdit(); await load(); } catch (e) { error.value = String(e); } finally { saving.value = false; } }
async function remove(product: Product) { if (!window.confirm(`Hapus produk ${product.name}? Produk yang memiliki varian tidak dapat dihapus.`)) return; try { await invoke("delete_product", { productId: product.id }); await load(); } catch (e) { error.value = String(e); } }
onMounted(load);
</script>

<template><section class="module-page"><div class="section-intro"><div><p class="eyebrow">Katalog</p><h2>Produk dan varian</h2><p class="intro-copy">Produk adalah identitas umum; varian menyimpan SKU, harga, dan stok secara mandiri.</p></div><button class="secondary-button" type="button" @click="load"><RefreshCw :size="15" /> Segarkan</button></div><div class="content-columns"><form class="panel form-panel" @submit.prevent="save"><div class="panel-heading"><div><p class="eyebrow">{{ editingId ? "Perubahan" : "Data baru" }}</p><h3>{{ editingId ? "Edit produk" : "Tambah produk" }}</h3></div><component :is="editingId ? X : Plus" :size="18" class="panel-icon" /></div><label>Nama produk<input v-model="name" placeholder="Contoh: Keripik Balado" /></label><label>Kategori <span class="optional">opsional</span><select v-model="categoryId"><option :value="null">Tanpa kategori</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></label><label>Deskripsi <span class="optional">opsional</span><textarea v-model="description" rows="4"></textarea></label><p v-if="error" class="form-error">{{ error }}</p><div class="action-row"><button class="primary-button" :disabled="saving" type="submit">{{ saving ? "Menyimpan..." : editingId ? "Simpan perubahan" : "Simpan produk" }}</button><button v-if="editingId" class="secondary-button" type="button" @click="cancelEdit">Batal</button></div></form><section class="panel table-panel paginated-panel"><div class="panel-heading"><div><p class="eyebrow">Daftar aktif</p><h3>Produk</h3></div><span class="neutral-chip">{{ products.length }} produk</span></div><div v-if="loading" class="table-state">Memuat data...</div><div v-else-if="!products.length" class="table-state"><Package :size="22" /><strong>Belum ada produk</strong><span>Tambahkan produk sebelum membuat varian.</span></div><template v-else><table><thead><tr><th>Nama produk</th><th>Kategori</th><th>Varian</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="product in pagedProducts" :key="product.id"><td class="cell-strong">{{ product.name }}</td><td>{{ product.category_name || "—" }}</td><td>{{ product.variant_count }}</td><td><span class="status-label">{{ product.is_active ? "Aktif" : "Nonaktif" }}</span></td><td class="row-actions"><button type="button" @click="edit(product)">Edit</button><button type="button" @click="remove(product)">Hapus</button></td></tr></tbody></table><PaginationControls v-model:page="page" :total="products.length" :page-size="pageSize" /></template></section></div></section></template>
